import{_ as o,C as l,c as s,o as r,at as e,G as n,w as d}from"./chunks/framework.B-8aa_PR.js";const m=JSON.parse('{"title":"智能体范式 Plan-and-Solve","description":"","frontmatter":{},"headers":[],"relativePath":"ai_thinking/从零开始构建智能体/Plan-and-Solve.md","filePath":"ai_thinking/从零开始构建智能体/Plan-and-Solve.md","lastUpdated":1771408012000}'),p={name:"ai_thinking/从零开始构建智能体/Plan-and-Solve.md"};function c(h,a,_,u,A,E){const i=l("MermaidChart"),t=l("ClientOnly");return r(),s("div",null,[a[0]||(a[0]=e(`<h1 id="智能体范式-plan-and-solve" tabindex="-1">智能体范式 Plan-and-Solve <a class="header-anchor" href="#智能体范式-plan-and-solve" aria-label="Permalink to &quot;智能体范式 Plan-and-Solve&quot;">​</a></h1><h2 id="_1-plan-and-solve-是什么" tabindex="-1">1. Plan-and-Solve 是什么 <a class="header-anchor" href="#_1-plan-and-solve-是什么" aria-label="Permalink to &quot;1. Plan-and-Solve 是什么&quot;">​</a></h2><ul><li>核心思路：在行动前先让 LLM 给出一份粗粒度计划（Plan），确认后再逐步执行（Solve），必要时根据执行反馈调整计划。</li><li>流程拆成两段：先“想清楚要做什么”，再“按部就班去做”，避免一边执行一边走偏。</li><li>目标：提升长序列任务的成功率、可解释性与可控性，减少盲目试错和无谓的工具调用。</li></ul><h2 id="_2-与-react-的对比" tabindex="-1">2. 与 ReAct 的对比 <a class="header-anchor" href="#_2-与-react-的对比" aria-label="Permalink to &quot;2. 与 ReAct 的对比&quot;">​</a></h2><ul><li>ReAct：Thought/Action/Observation 交替，决策与执行交织，适合短任务、即时响应。</li><li>Plan-and-Solve：先产出全局计划，再按计划执行，适合步骤较多、需要全局视角的任务（如多轮检索、代码修改、数据处理流水线）。</li><li>互补关系：可在计划阶段使用思维链，执行阶段仍可用 ReAct 风格的工具调用；计划不必过细，保持可调整。</li></ul><h2 id="_3-prompt-设计要点" tabindex="-1">3. Prompt 设计要点 <a class="header-anchor" href="#_3-prompt-设计要点" aria-label="Permalink to &quot;3. Prompt 设计要点&quot;">​</a></h2><ul><li>显式要求“先计划再执行”，并约定输出格式（如 <code>Plan:</code>、<code>Step 1...</code>）。</li><li>约束计划粒度：条目化、每步可验证，可在 3-7 步内完成；禁止把答案直接写进计划。</li><li>执行阶段强调遵循计划，并在需要时短暂更新计划（<code>Update Plan</code>），避免频繁推倒重来。</li><li>给出示例计划和执行示例，帮助模型理解格式与期望。</li></ul><p>极简模板示例：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你将先给出计划，再逐步执行。不要在计划中直接回答。</span></span>
<span class="line"><span>Plan:</span></span>
<span class="line"><span>1) ...</span></span>
<span class="line"><span>2) ...</span></span>
<span class="line"><span>3) ...</span></span>
<span class="line"><span>Execute:</span></span>
<span class="line"><span>- 按步骤进行，必要时简短更新计划，最后输出 Answer。</span></span></code></pre></div><h2 id="_4-运行流程" tabindex="-1">4. 运行流程 <a class="header-anchor" href="#_4-运行流程" aria-label="Permalink to &quot;4. 运行流程&quot;">​</a></h2><ol><li>接收任务与约束，提示模型先生成计划（含步数上限、检查项）。</li><li>人或系统检查计划：可自动校验步数、是否可执行、是否跑题。</li><li>进入执行循环：按步骤调用工具/推理，记录 Observation，并标记完成的步骤。</li><li>若遇阻碍：允许少量的“微调计划”或追加步骤，避免无限重规划。</li><li>收尾：总结执行结果，给出最终 Answer，并附带已完成步骤或遗留问题。</li></ol>`,11)),n(t,null,{default:d(()=>[n(i,{code:"flowchart%20TD%0A%20%20U%5B%E7%94%A8%E6%88%B7%E9%9C%80%E6%B1%82%5D%20--%3E%20P%5B%E7%94%9F%E6%88%90%20Plan%5D%0A%20%20P%20--%3E%20C%7B%E8%AE%A1%E5%88%92%E5%8F%AF%E8%A1%8C%3F%7D%0A%20%20C%20--%3E%7C%E6%98%AF%7C%20E%5B%E9%80%90%E6%AD%A5%E6%89%A7%E8%A1%8C%5D%0A%20%20C%20--%3E%7C%E5%90%A6%7C%20R%5B%E8%B0%83%E6%95%B4%E8%AE%A1%E5%88%92%5D%0A%20%20E%20--%3E%20B%7B%E5%8D%A1%E4%BD%8F%3F%7D%0A%20%20B%20--%3E%7C%E5%90%A6%7C%20A%5BAnswer%5D%0A%20%20B%20--%3E%7C%E6%98%AF%7C%20R%0A",showToolbar:"1"})]),_:1}),a[1]||(a[1]=e('<h2 id="_5-优势" tabindex="-1">5. 优势 <a class="header-anchor" href="#_5-优势" aria-label="Permalink to &quot;5. 优势&quot;">​</a></h2><ul><li>全局性：先拿到路线图，减少局部最优和瞎试错。</li><li>可控性：计划可审查、可插入规则（步数/成本/安全限制）。</li><li>可解释：计划 + 执行记录天然形成过程文档，便于复现和调试。</li><li>成本友好：减少无效工具调用；对固定流程任务更高效。</li></ul><h2 id="_6-局限与风险" tabindex="-1">6. 局限与风险 <a class="header-anchor" href="#_6-局限与风险" aria-label="Permalink to &quot;6. 局限与风险&quot;">​</a></h2><ul><li>计划质量依赖模型：若计划阶段出错，后续执行难以补救。</li><li>刚性与拖延：计划过细可能僵化，过宽又缺少约束；生成计划本身也有成本。</li><li>计划-执行偏移：执行中环境变化或信息缺失，计划易失效，需要再规划策略。</li><li>幻觉与安全：计划或执行都可能编造步骤/数据，需要校验与权限控制。</li></ul><h2 id="_7-缓解策略" tabindex="-1">7. 缓解策略 <a class="header-anchor" href="#_7-缓解策略" aria-label="Permalink to &quot;7. 缓解策略&quot;">​</a></h2><ul><li>计划质量控制：限制步数、禁止直接给答案、要求每步可验证；必要时加自动审查规则。</li><li>执行保护：设置最大回合数/超时；对关键动作做参数校验或人工确认。</li><li>自检与更新：鼓励在每步后自检，允许“轻量再规划”而非推倒重来。</li><li>评估指标：成功率、计划-执行一致性、步数/成本、可解释性、安全合规性。</li></ul><h2 id="_8-适用场景与小贴士" tabindex="-1">8. 适用场景与小贴士 <a class="header-anchor" href="#_8-适用场景与小贴士" aria-label="Permalink to &quot;8. 适用场景与小贴士&quot;">​</a></h2><ul><li>场景：多步信息收集与汇总、代码/配置修改流水线、数据清洗/分析、文档编排、需要可审核步骤的任务。</li><li>小贴士：让模型先列“已知/未知/需查询”；计划保持 3-7 步；在执行阶段保留“轻量修正计划”的出口；对关键工具调用加上格式示例和参数校验。</li></ul>',8))])}const C=o(p,[["render",c]]);export{m as __pageData,C as default};
